package agent

import (
	"bytes"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/binary"
	"time"

	agentv1 "github.com/saker-ai/grayling/api/agent/v1"
)

// RecoverySignatureDomain is independent of ordinary resource signatures.
const RecoverySignatureDomain = "grayling.agent.v1.epoch-recovery\x00"
const maxRecoveryBytes = 8192

// RecoveryClaims authorizes exactly one transition from the saved watermark
// to a complete signed policy, including its signer, validity and hashes.
// Nonce is independently generated by the recovery authority for auditability.
type RecoveryClaims struct {
	From                        Watermark
	Target                      Claims
	Nonce                       [32]byte
	KeyID                       string
	IssuedUnixMs, ExpiresUnixMs int64
}
type RecoveryGrant struct{ Claims, Signature []byte }

// RecoveryVerifier holds independently provisioned recovery roots. PolicyCache
// refuses keys shared with its ordinary policy trust ring, even under aliases.
type RecoveryVerifier struct{ roots *Verifier }

func NewRecoveryVerifier(keys map[string]TrustKey) (*RecoveryVerifier, error) {
	roots, err := NewVerifier(keys)
	if err != nil {
		return nil, err
	}
	return &RecoveryVerifier{roots: roots}, nil
}
func (r RecoveryClaims) valid() bool {
	return validWatermark(r.From) && r.From != (Watermark{}) && r.Target.valid() && (r.Target.Kind == agentv1.ResourceKind_RESOURCE_KIND_POLICY || r.Target.Kind == agentv1.ResourceKind_RESOURCE_KIND_DISCOVERY) && r.Target.ControlPlaneEpoch > r.From.ControlPlaneEpoch && r.Nonce != [32]byte{} && validText(r.KeyID) && r.IssuedUnixMs > 0 && r.ExpiresUnixMs > r.IssuedUnixMs && r.ExpiresUnixMs-r.IssuedUnixMs <= int64(15*time.Minute/time.Millisecond)
}

// MarshalRecoveryClaims defines GRA1: target length/claims, previous watermark,
// nonce, grant validity, and length-prefixed recovery key ID; all integers big endian.
func MarshalRecoveryClaims(r RecoveryClaims) ([]byte, error) {
	if !r.valid() {
		return nil, ErrResource
	}
	target, err := MarshalClaims(r.Target)
	if err != nil {
		return nil, err
	}
	b := binary.BigEndian.AppendUint32([]byte("GRA1"), uint32(len(target)))
	b = append(b, target...)
	b = appendMark(b, r.From)
	b = append(b, r.Nonce[:]...)
	b = binary.BigEndian.AppendUint64(b, uint64(r.IssuedUnixMs))
	b = binary.BigEndian.AppendUint64(b, uint64(r.ExpiresUnixMs))
	b = binary.BigEndian.AppendUint16(b, uint16(len(r.KeyID)))
	return append(b, r.KeyID...), nil
}
func ParseRecoveryClaims(b []byte) (RecoveryClaims, error) {
	var r RecoveryClaims
	if len(b) < 138 || len(b) > maxRecoveryBytes || string(b[:4]) != "GRA1" {
		return r, ErrResource
	}
	rawSize := binary.BigEndian.Uint32(b[4:8])
	if rawSize > maxClaimsBytes || uint64(rawSize) > uint64(len(b)-138) {
		return r, ErrResource
	}
	size := int(rawSize)
	target, err := ParseClaims(b[8 : 8+size])
	if err != nil {
		return r, err
	}
	r.Target = target
	rest := b[8+size:]
	r.From = readMark(rest[:80])
	copy(r.Nonce[:], rest[80:112])
	r.IssuedUnixMs = int64(binary.BigEndian.Uint64(rest[112:120]))
	r.ExpiresUnixMs = int64(binary.BigEndian.Uint64(rest[120:128]))
	keySize := int(binary.BigEndian.Uint16(rest[128:130]))
	if keySize != len(rest)-130 {
		return r, ErrResource
	}
	r.KeyID = string(rest[130:])
	if !r.valid() {
		return RecoveryClaims{}, ErrResource
	}
	return r, nil
}
func independentRecoveryRoots(recovery *RecoveryVerifier, policy *Verifier) bool {
	if recovery == nil {
		return true
	}
	if recovery.roots == nil || policy == nil {
		return false
	}
	for _, a := range recovery.roots.keys {
		for _, b := range policy.keys {
			if bytes.Equal(a.PublicKey, b.PublicKey) {
				return false
			}
		}
	}
	return true
}
func (v *RecoveryVerifier) verify(grant *RecoveryGrant, scope Scope, key string, now time.Time) (RecoveryClaims, [32]byte, error) {
	if v == nil || v.roots == nil || grant == nil || len(grant.Signature) != ed25519.SignatureSize {
		return RecoveryClaims{}, [32]byte{}, ErrResource
	}
	r, err := ParseRecoveryClaims(grant.Claims)
	if err != nil {
		return r, [32]byte{}, err
	}
	root, ok := v.roots.keys[r.KeyID]
	if !ok || !ed25519.Verify(root.PublicKey, append([]byte(RecoverySignatureDomain), grant.Claims...), grant.Signature) {
		return r, [32]byte{}, ErrResource
	}
	if r.Target.Scope != scope || r.Target.Key != key {
		return r, [32]byte{}, ErrScope
	}
	if now.Before(root.NotBefore) || !now.Before(root.NotAfter) || now.UnixMilli() < r.IssuedUnixMs || now.UnixMilli() >= r.ExpiresUnixMs || time.UnixMilli(r.IssuedUnixMs).Before(root.NotBefore) || time.UnixMilli(r.ExpiresUnixMs).After(root.NotAfter) {
		return r, [32]byte{}, ErrExpired
	}
	digest := sha256.Sum256(append(bytes.Clone(grant.Claims), grant.Signature...))
	return r, digest, nil
}
